(272, 'vivuroy85@gmail.com', 'hr@thesvpacademy.com', 'Welcome SVP-Academy', '<section class=\"content\">\r\n    <div class=\"container-fluid\">\r\n        <div class=\"row\">\r\n            <div class=\"col-md-12\">\r\n                <!-- For Messages -->\r\n                <div class=\"template-alert-block\"></div>\r\n                <div class=\"card card-primary\">\r\n                    <div class=\"card-header\">\r\n                        <h3 class=\"card-title font-weight-bold\">\r\n                            <i class=\'fa fa-plus-square\'></i>&nbsp; </i>                        </h3>\r\n                    </div>\r\n\r\n                    <div class=\"card-body append_place\">\r\n                        <div class=\"row\">\r\n                            <div class=\"col-md-12\">\r\n                                <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\r\n                                    <tbody>\r\n                                        <tr>\r\n                                            <td>&nbsp;</td>\r\n                                            <td class=\"container\">\r\n                                                <div class=\"content\">\r\n                                                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\r\n                                                        <tbody>\r\n                                                            <tr>\r\n                                                                <td style=\"text-align: center;\">\r\n                                                                    <div style=\"height: 70px;width:100%;text-align: center;margin-bottom: 10px;\">\r\n                                                                        <a href=\"https://thesvpacademy.com/admin/\">\r\n                                                                        </a>\r\n                         