(279, 'monojpande43@gmail.com', 'hr@thesvpacademy.com', 'Welcome SVP-Academy', '<section class=\"content\">\r\n    <div class=\"container-fluid\">\r\n        <div class=\"row\">\r\n            <div class=\"col-md-12\">\r\n                <!-- For Messages -->\r\n                <div class=\"template-alert-block\"></div>\r\n                <div class=\"card card-primary\">\r\n                    <div class=\"card-header\">\r\n                        <h3 class=\"card-title font-weight-bold\">\r\n                            <i class=\'fa fa-plus-square\'></i>&nbsp; </i>                        </h3>\r\n                    </div>\r\n\r\n                    <div class=\"card-body append_place\">\r\n                        <div class=\"row\">\r\n                            <div class=\"col-md-12\">\r\n                                <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\r\n                                    <tbody>\r\n                                        <tr>\r\n                                            <td>&nbsp;</td>\r\n                                            <td class=\"container\">\r\n                                                <div class=\"content\">\r\n                                                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\r\n                                                        <tbody>\r\n                                                            <tr>\r\n                                                                <td style=\"text-align: center;\">\r\n                                                                    <div style=\"height: 70px;width:100%;text-align: center;margin-bottom: 10px;\">\r\n                                                                        <a href=\"https://thesvpacademy.com/admin/\">\r\n                                                                        </a>\r\n                                                                    </div>\r\n                                                                </td>\r\n                                                            </tr>\r\n                                                        </tbody>\r\n                                                    </table> <!-- START CENTERED WHITE CONTAINER -->\r\n\r\n                                                    <table role=\"presentation\" class=\"main\">\r\n                                                        <!-- START MAIN CONTENT AREA -->\r\n                                                        <tbody>\r\n                                                            <tr>\r\n                                                                <td class=\"wrapper\">\r\n                                                                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n                                                                        <tbody>\r\n                                                                            <tr>\r\n                                                                                <td>\r\n                                                                                    <h1 style=\"text-decoration: none; font-size: 24px;line-height: 28px;font-weight: bold\"></h1>\r\n                                                                                    <div class=\"mailcontent\" style=\"line-height: 26px;font-size: 14px;\">\r\n                                                                                        <div class=\"mailcontent\" style=\"line-height: 26px;font-size: 14px;\">\r\n                                                                                            <p><b><p>Dear  User  Refrral\n\n</p><br><p>Welcome to SVP Academy, where Passion meets Practice!</p><br><p>We\'re thrilled that you\'ve chosen to join our musical community. Whether you\'re an experienced musician or just starting your musical journey, you\'re in the right place.</p><br><p>Our dedicated team of passionate instructors, state-of-the-art facilities, and a vibrant community of fellow musicians are all here to support you every step of the way. You\'ll find that our academy is not just a place for learning but a warm and inclusive family where you can freely express yourself through the universal language of music. Don\'t hesitate to ask questions, explore new genres, and make lasting connections with fellow musicians.</p><br><p>Feel free to reach out to us if you have any questions or need assistance \n\n<b>at <a href=\"\" title=\"Link: null\">operations@thesvpacademy.com</a></b>\n\n. We\'re here to ensure your time at SVP Academy is enriching and enjoyable.</p><br><p>Let\'s make beautiful music together!</p><br><p>Musically Yours,<br>Team SVP</p></b>\n\n<div><a target=\"\" rel=\"\"></a></div></p>\r\n                                                                                        </div>\r\n                                                                                    </div>\r\n                                                                                </td>\r\n                                                                            </tr>\r\n                                                                        </tbody>\r\n                                                                    </table>\r\n                                                                </td>\r\n                                                            </tr>\r\n                                                            <!-- END MAIN CONTENT AREA -->\r\n                                                        </tbody>\r\n                                                    </table>\r\n\r\n                                                    <!-- SOCIAL LINKS -->\r\n                                                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"margin-top: 10px;\">\r\n                                                        <tbody>\r\n                                                            <tr>\r\n                                                                <td class=\"content-block\" style=\"text-align: center;width: 100%;\">\r\n                                                                                                                                    </td>\r\n                                                            </tr>\r\n                                                        </tbody>\r\n                                                    </table>\r\n\r\n                                                    <!-- START FOOTER -->\r\n                                                    <div class=\"footer\">\r\n                                                        <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n                                                            <tbody>\r\n                                                                <tr>\r\n                                                                    <td class=\"content-block powered-by\">\r\n\r\n                                                                    </td>\r\n                                                                </tr>\r\n\r\n                                                            </tbody>\r\n                                                        </table>\r\n                                                    </div>\r\n                                                    <!-- END FOOTER -->\r\n\r\n                                                    <!-- END CENTERED WHITE CONTAINER -->\r\n                                                </div>\r\n                                            </td>\r\n                                            <td>&nbsp;</td>\r\n                                        </tr>\r\n                                    </tbody>\r\n                                </table>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>', 0, '2024-02-24 12:40:43', '2024-02-24 12:41:02', 1, 1),
(280, 'arpitapall2620@gmail.com', 'hr@thesvpacademy.com', 'Reminder: Your Upcoming Music Class', '<section class=\"content\">\r\n    <div class=\"container-fluid\">\r\n        <div class=\"row\">\r\n            <div class=\"col-md-12\">\r\n                <!-- For Messages -->\r\n                <div class=\"template-alert-block\"></div>\r\n                <div class=\"card card-primary\">\r\n                    <div class=\"card-header\">\r\n                        <h3 class=\"card-title font-weight-bold\">\r\n                            <i class=\'fa fa-plus-square\'></i>&nbsp; </i>                        </h3>\r\n                    </div>\r\n\r\n                    <div class=\"card-body append_place\">\r\n                        <div class=\"row\">\r\n                            <div class=\"col-md-12\">\r\n                                <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\r\n                                    <tbody>\r\n                                        <tr>\r\n                                            <td>&nbsp;</td>\r\n                                            <td class=\"container\">\r\n                                                <div class=\"content\">\r\n                                                    <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\r\n                                                        <tbody>\r\n                                                            <tr>\r\n                                                                <td style=\"text-align: center;\">\r\n                                                                    <div style=\"height: 70px;width:100%;text-align: center;margin-bottom: 10px;\">\r\n                                                                        <a href=\"https://thesvpacademy.com/admin/\">\r\n                                                                        </a>\r\n    